import{_ as o,o as r,c as a,af as t}from"./chunks/framework._zKnALF5.js";const m=JSON.parse('{"title":"更新日志","description":"","frontmatter":{},"headers":[],"relativePath":"changelog/index.md","filePath":"changelog/index.md","lastUpdated":null}'),d={name:"changelog/index.md"};function c(n,e,s,l,i,g){return r(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h1><p>以下为 <strong>小游码匠 · xymj-colyseus-server</strong> 面向集成方的版本说明，便于您在接入、联调与升级时了解能力边界与注意事项。</p><p>更完整的协议与示例见站内各专题文档；服务端仓库内的 <strong><code>CHANGELOG.md</code></strong> 与本文内容保持一致，亦可在 GitHub 直接查看：<a href="https://github.com/PengYiZhen/xymj-colyseus-server/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">https://github.com/PengYiZhen/xymj-colyseus-server/blob/main/CHANGELOG.md</a></p><p>版本号遵循 <a href="https://semver.org/lang/zh-CN/" target="_blank" rel="noreferrer">语义化版本</a>，条目风格参考 <a href="https://keepachangelog.com/zh-CN/1.0.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>。升级前请确认运行环境满足 <a href="/guide/installation.html">安装指南</a>。</p><h2 id="文档同步-2026-05-19" tabindex="-1">文档同步（2026-05-19） <a class="header-anchor" href="#文档同步-2026-05-19" aria-label="Permalink to &quot;文档同步（2026-05-19）&quot;">​</a></h2><p>与 <strong><code>xymj-colyseus-server</code> v1.1.0</strong> 源码对齐的文档修订（无服务端版本号变更）：</p><ul><li><strong>匹配</strong>：补充 <code>gameRoomName</code>（客户端可传、默认 <code>game_room</code>）、<code>MATCH_DEFAULT_GAME_ROOM</code> / <code>MATCH_MODE_GAME_ROOM_MAP</code>；明确 <code>skill</code> / <code>tags</code> 当前仅挂票据、<strong>FIFO 撮合</strong>；新增 <code>match:error</code>；Party <code>user</code> 展示字段、<code>party:update.members</code>、<code>party:start</code> 人数规则；<strong><code>match:found</code> → <code>joinById(roomId)</code></strong> 与 <code>roomName</code> / <code>game_room</code> 区别、双连接说明。</li><li><strong>配置</strong>：<a href="/guide/configuration.html">配置说明</a> 增加匹配相关环境变量表。</li></ul><h2 id="_1-1-0-2026-05-07" tabindex="-1">[1.1.0] - 2026-05-07 <a class="header-anchor" href="#_1-1-0-2026-05-07" aria-label="Permalink to &quot;[1.1.0] - 2026-05-07&quot;">​</a></h2><h3 id="本版定位" tabindex="-1">本版定位 <a class="header-anchor" href="#本版定位" aria-label="Permalink to &quot;本版定位&quot;">​</a></h3><p>当前 <strong>推荐集成基线</strong>。在此版本上，您可获得与本文档一致的 <strong>HTTP 鉴权、匹配开房、多频道聊天、帧同步对局</strong> 等约定实现，并可直接使用服务端仓库内静态演示页做联调。</p><h3 id="您可依赖的能力" tabindex="-1">您可依赖的能力 <a class="header-anchor" href="#您可依赖的能力" aria-label="Permalink to &quot;您可依赖的能力&quot;">​</a></h3><ul><li><strong>匹配与开房（<code>matchmaker_room</code>）</strong>：主动匹配（<code>match:find</code> / <code>match:cancel</code>）、Party 房间码（<code>party:create</code> / <code>party:join</code> / <code>party:start</code>），组局成功后由服务端下发 <code>match:found</code>，客户端再 <code>joinById</code> 进入 <code>game_room</code>。<strong>使用本能力前请部署 Redis</strong>，详见 <a href="/guide/installation.html">安装指南</a>、<a href="/rooms/matchmaking.html">匹配与开房</a>。</li><li><strong>帧同步对局（<code>game_room</code>）</strong>：固定帧率、<code>input</code> 消息与 Schema 状态同步；支持匹配下发的 <code>matchId</code>、<code>seatIndex</code>、<code>reconnectKey</code> 等与断线重连相关的约定字段。详见 <a href="/rooms/frame-sync-game-room.html">帧同步与游戏房</a>。</li><li><strong>多模式聊天（<code>chat_world_room</code> 等）</strong>：世界 / 工会 / 附近 / 队伍四类频道；进房 options 需携带 JWT，并按频道补充 <code>guildId</code>、<code>teamId</code>、坐标与 <code>nearbyRadius</code> 等。<strong>世界频道</strong>在多进程部署时依赖 <strong>Redis Pub/Sub</strong>。详见 <a href="/rooms/messages.html">多模式聊天</a>。</li><li><strong>HTTP API</strong>：基于 <code>routing-controllers</code> 的装饰器路由；<strong>Swagger</strong>（<code>/api-docs</code>）提供可交互接口文档。注册、登录及微信 / 抖音小游戏登录等接口签发的访问令牌，与 Colyseus 进房时的 <strong><code>token</code> / <code>accessToken</code></strong> 对齐。详见 <a href="/reference/api.html">API 概览</a>、<a href="/guide/jwt-room-auth.html">JWT 与房间鉴权</a>。</li><li><strong>数据与中间件</strong>：TypeORM（MySQL/MariaDB）、Redis（会话、匹配队列、聊天广播等）；房间侧 JWT 校验使用 <strong><code>@RequireAuth()</code></strong>，与 Redis 中访问令牌状态联动。详见 <a href="/rooms/auth.html">鉴权与权限</a>。</li><li><strong>联调资源</strong>：服务端 <code>src/public</code> 下提供 <strong><code>MatchmakingDemo.html</code></strong>、<strong><code>ChatDemo.html</code></strong>、<strong><code>FrameSync.html</code></strong> 等，便于您在拿到 JWT 后快速验证消息流。详见 <a href="/guide/getting-started.html">快速入门</a>。</li></ul><h3 id="升级与环境提示" tabindex="-1">升级与环境提示 <a class="header-anchor" href="#升级与环境提示" aria-label="Permalink to &quot;升级与环境提示&quot;">​</a></h3><ul><li>运行环境要求 <strong>Node.js ≥ 20.9.0</strong>；使用匹配或世界频道跨实例能力时，请保证 <strong>Redis</strong> 可用并按 <a href="/guide/configuration.html">配置说明</a> 配置连接。</li><li><strong>压测房间 <code>loadtest_room</code></strong> 默认不做 JWT 校验，仅用于容量与延迟摸底；<strong>上线环境请务必关闭或限制访问</strong>（见 <a href="/ops/load-testing.html">人数压力测</a> 与环境变量说明）。</li></ul><h3 id="问题与贡献" tabindex="-1">问题与贡献 <a class="header-anchor" href="#问题与贡献" aria-label="Permalink to &quot;问题与贡献&quot;">​</a></h3><ul><li>源码与缺陷跟踪：<a href="https://github.com/PengYiZhen/xymj-colyseus-server" target="_blank" rel="noreferrer">https://github.com/PengYiZhen/xymj-colyseus-server</a></li><li>若您从更早的私有分支或模板合并而来，合并后请对照本页与 <a href="/reference/protocol.html">消息协议</a> 核对 <strong>房间名、环境变量与 Redis 依赖</strong> 是否与当前版本一致。</li></ul><h2 id="_1-0-0" tabindex="-1">[1.0.0] <a class="header-anchor" href="#_1-0-0" aria-label="Permalink to &quot;[1.0.0]&quot;">​</a></h2><h3 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>首个对外整合形态：<strong>JWT 鉴权</strong>、示例 <strong><code>my_room</code></strong>、基础认证相关 HTTP API 与可扩展的房间注册方式。</p><p>若您从 <strong>1.0.x</strong> 集成线升级到 <strong>1.1.0</strong>，请重点补齐 <strong>Redis</strong>、核对新增房间类型（<code>matchmaker_room</code>、<code>game_room</code>、<code>chat_*</code>）及静态资源路径，避免客户端仍使用已废弃的单一示例房间假设。</p>',20)])])}const u=o(d,[["render",c]]);export{m as __pageData,u as default};
